def icon_for(agent: str) -> dict[str, Any]:
    """Look up an icon by adapter name, falling back to a neutral mark."""
    return ICONS.get(agent, ICONS["_default"])


# A vendor SVG whose <clipPath> element is empty, while a <g clip-path="url(#...)">
# still points at it, renders as a completely blank image: everything inside the
# group is clipped to an empty region. WorkBuddy's published logo has exactly this
# defect, so the mark came out invisible. Dropping the dangling reference restores
# the artwork, and is a no-op for every SVG that does not have the problem.
_EMPTY_CLIPPATH = re.compile(
    r"<clipPath\b[^>]*>\s*</clipPath>",
    re.IGNORECASE | re.DOTALL,
)
_CLIP_ATTR = re.compile(
    r"""\s+clip-path\s*=\s*["']url\(#([^)"']+)\)["']""",
    re.IGNORECASE,
)
_CLIPPATH_ID = re.compile(r"""<clipPath\b[^>]*\bid\s*=\s*["']([^"']+)["']""", re.IGNORECASE)


def _strip_dangling_clippath(svg: str) -> str:
    """Remove clipPath elements that are empty and the references to them."""
    ids = {
        cid for cid in _CLIPPATH_ID.findall(svg)
        if re.search(
            r"""<clipPath\b[^>]*\bid\s*=\s*["']%s["'][^>]*>\s*</clipPath>""" % re.escape(cid),
            svg, re.IGNORECASE | re.DOTALL,
        )
    }
    if not ids:
        return svg
    for cid in ids:
        svg = re.sub(
            r"""<clipPath\b[^>]*\bid\s*=\s*["']%s["'][^>]*>\s*</clipPath>""" % re.escape(cid),
            "", svg, flags=re.IGNORECASE | re.DOTALL,
        )
        svg = re.sub(
            r"""\s+clip-path\s*=\s*["']url\(#%s\)["']""" % re.escape(cid),
            "", svg, flags=re.IGNORECASE,
        )
    return svg


def _repair_svg_data_uri(src: str) -> str:
    """Apply the clipPath repair to a ``data:image/svg+xml;base64,`` URI."""
    marker = "data:image/svg+xml;base64,"
    if not src.startswith(marker):
        return src
    try:
        raw = base64.b64decode(src[len(marker):])
        fixed = _strip_dangling_clippath(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return src
    if fixed.encode("utf-8") == raw:
        return src
    return marker + base64.b64encode(fixed.encode("utf-8")).decode("ascii")


def icons_json() -> dict[str, dict[str, Any]]:
    """Serialisable icon table for the dashboard (``/api/icons``)."""
    out: dict[str, dict[str, Any]] = {}
    for name, icon in ICONS.items():
        if icon.get("kind") == "svg" and isinstance(icon.get("src"), str):
            src = _repair_svg_data_uri(icon["src"])
            if src != icon["src"]:
                icon = {**icon, "src": src}
        out[name] = icon
    return out
